function ownerSetup(origin, token, recovery) {
  return `<p class="lead">${recovery ? "Choose a new password for" : "Create a password to protect"} the Publisher running in your Cloudflare account.</p><div class="identity"><span>Your private Publisher</span><strong>${escapeHtml(new URL(origin).hostname)}</strong><p>This password signs you in to this control panel, hosted in your Cloudflare account.</p></div><form method="post">${hidden("token", token)}<label for="owner-password">${recovery ? "New password" : "Owner password"}</label><input id="owner-password" type="password" name="password" minlength="12" maxlength="256" autocomplete="new-password" aria-describedby="password-help" required><p id="password-help" class="help">Use at least 12 characters. Your password manager can generate and save one for this address.</p><button>${recovery ? "Save new password" : "Create password and open Publisher"}</button></form><p class="help">Next: connect website publishing in Settings, then add this Publisher to ChatGPT.</p>`;
}
