// src/dashboard.ts
function dashboard(input2) {
  const {
    origin,
    account,
    version: version2,
    csrf,
    projects,
    operations,
    connected,
    update,
    receipt
  } = input2;
  const rows = projects.projects.map(
    (p) => `<article class="project-row"><div class="project-title"><h3>${escapeHtml(p.name)}</h3><span class="status ${p.live ? "live" : ""}">${p.live ? "Published" : "Private / unpublished"}</span></div><a class="project-url" href="${escapeHtml(p.url)}" target="_blank" rel="noreferrer">${escapeHtml(new URL(p.url).hostname)} \u2197</a><details><summary>Manage project</summary><small>Project ID: ${escapeHtml(p.id)}</small><div class="project-actions">${p.head ? form("/export", csrf, hidden("project", p.id) + '<button class="quiet-button">Export files</button>') : ""}${form("/unpublish", csrf, hidden("project", p.id) + hidden("base", p.head) + '<button class="quiet-button">Unpublish</button>')}</div><details><summary>Delete permanently</summary>${form("/delete", csrf, hidden("project", p.id) + hidden("base", p.head) + `<label>Enter <code>${escapeHtml(p.id)}</code> to delete this project and its history<input name="confirmation" required autocomplete="off"></label><button class="danger">Delete project permanently</button>`)}</details></details></article>`
  ).join("");
  const activity = operations.map((op) => {
    const project = projects.projects.find((p) => p.id === op.project);
    return `<article class="operation"><div class="operation-head"><strong>${escapeHtml(project?.name ?? op.kind)}</strong><span>${escapeHtml(op.state)}</span></div><time datetime="${escapeHtml(new Date(op.created).toISOString())}">${escapeHtml(new Date(op.created).toISOString().replace("T", " ").slice(0, 16))} UTC \xB7 ${escapeHtml(op.kind)}</time>${op.reachable === false ? "<p>Awaiting public address availability</p>" : ""}${op.error ? `<p>${escapeHtml(op.error.message)}</p>` : ""}<details><summary>Operation details</summary><code>${escapeHtml(op.id)}</code><p>Attempts: ${escapeHtml(op.attempts)}</p></details></article>`;
  }).join("");
  return `<div class="workspace"><section class="panel projects-panel"><div class="panel-heading"><h2>Your public projects</h2><small>${projects.projects.length} projects \xB7 ${(projects.retained_bytes / 1024 / 1024).toFixed(2)} / 250 MiB</small></div><div class="panel-scroll" tabindex="0" role="region" aria-label="Projects">${rows || '<div class="empty"><strong>Your first site starts in a chat.</strong><p>Connect ChatGPT, choose the files you want to share, and ask Publisher to publish them here.</p></div>'}${projects.next_cursor ? '<p class="help">Showing the first 50 projects. Ask Publisher in ChatGPT to list more.</p>' : ""}</div></section>
<section class="panel connect-panel" id="installation-receipt"><div class="panel-heading"><h2>ChatGPT connection</h2></div><div class="panel-scroll" tabindex="0" role="region" aria-label="ChatGPT connection and installation receipt"><p>Publish from a chat. Pick up from any session.</p><label for="mcp-url">MCP server URL</label><input id="mcp-url" readonly value="${escapeHtml(origin)}/mcp"><p class="help">Use this URL from your Cloudflare installation receipt in ChatGPT \u2192 Plugins \u2192 Add custom MCP server.</p><details><summary>Installation receipt & connection help</summary><p>If the option is missing, check Settings \u2192 Security and login \u2192 Developer mode. Availability depends on your ChatGPT account and workspace.</p><pre>${escapeHtml(JSON.stringify(receipt, null, 2))}</pre></details></div></section>
<section class="panel activity-panel"><div class="panel-heading"><h2>Recent operations</h2><a href="/" class="help">Refresh</a></div><div class="panel-scroll" tabindex="0" role="region" aria-label="Recent operations">${activity || "<p>No operations yet. Publication progress will appear here.</p>"}</div></section>
${cloudflareSettings(origin, account, csrf, connected)}
<section class="panel updates-panel"><div class="panel-heading"><h2>Publisher updates</h2></div><div class="panel-scroll" tabindex="0" role="region" aria-label="Publisher updates"><p>Installed version: <strong>${escapeHtml(version2)}</strong></p><p>Installed from: <a href="https://chatgpt-to-public.jumpermcp.dev/" target="_blank" rel="noreferrer">jumpermcp.dev</a></p><p>Update state: ${escapeHtml(update?.state ?? "No update checked")}.</p>${update?.error ? `<p role="alert">${escapeHtml(update.error.message)}</p>` : ""}${form("/updates/check", csrf, "<button>Check for updates</button>")}${update?.state === "review" ? `<h3>Review ${escapeHtml(update.release.manifest.version)}</h3><pre>${escapeHtml(update.release.manifest.notes)}</pre>${update.release.manifest.version === version2 ? '<p role="status">You already have this version installed.</p>' : form("/updates/apply", csrf, hidden("update", update.id) + "<button>Update Publisher</button>")}` : ""}<details><summary>How updates work</summary><p>Publishing pauses between steps during an update and resumes afterward. Your projects stay in your Cloudflare account.</p></details></div></section></div><div class="inline-meta"><small>${escapeHtml(new URL(origin).hostname)}</small><span class="status ${connected ? "live" : ""}">${connected ? "Website publishing connected" : "Connect Cloudflare in Settings"}</span></div>`;
}
